// The bundled dataset the plugin reads. The bundle text and its pin are embedded as constants in
// shipped-data.ts (generated by `cli.ts export --write-shipped`), so nothing is read from disk at
// run time and the pin travels with reviewed code. The shipped approved set is EMPTY until a human
// approves links.

import { validateBundle, type Bundle } from "./bundle.js";
import { SHIPPED_BUNDLE_JSON, SHIPPED_BUNDLE_PIN } from "./shipped-data.js";
import type { Outcome } from "./store.js";

let cached: Outcome<Bundle> | undefined;

// The pin is the only trust root: a bundle whose manifest does not hash to it is refused, never
// loaded "unpinned". `source` exists so a test can feed a tampered bundle through this exact
// wiring; production callers pass nothing and get the embedded constants (cached).
export function loadShippedBundle(source?: { readonly json: string; readonly pin: string }): Outcome<Bundle> {
  const load = (s: { readonly json: string; readonly pin: string }): Outcome<Bundle> => validateBundle(s.json, { expectedManifestSha256: s.pin });
  if (source !== undefined) return load(source);
  cached ??= load({ json: SHIPPED_BUNDLE_JSON, pin: SHIPPED_BUNDLE_PIN });
  return cached;
}
